css:
.ticker{position:relative;display:flex;align-items:center;overflow:hidden;
  height:30px;background:#111;color:#fff;
  margin-left:43px;margin-right:calc(50% - 50vw)}
.ticker__label{position:sticky;left:0;z-index:2;background:#111;flex:0 0 auto;
  padding:0 18px;font-size:11px;letter-spacing:.12em}
.ticker__items{display:flex;gap:24px;white-space:nowrap;animation:mq 28s linear infinite}
@keyframes mq{to{transform:translateX(-50%)}}

/* 罫の代わり版 */
.rule-ticker{font-size:9px;letter-spacing:.18em;color:#e39aa9;white-space:nowrap;
  overflow:hidden;border-bottom:1px solid #f1eaea;padding:14px 0}
@media(prefers-reduced-motion:reduce){.ticker__items{animation:none}}
